:root {
    --primary-color: #1a1a1a;
    --secondary-color: #f4f4f4;
    --accent-color: #3d5afe;
    --text-color: #333333;
    --text-light: #666666;
    --background-color: #ffffff;
    --container-width: 1200px;
    --font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --transition-speed: 0.3s;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-family);
    line-height: 1.6;
    color: var(--text-color);
    background-color: var(--background-color);
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 20px;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    border: 0;
}

/* Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: white;
    padding: 8px;
    z-index: 100;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

/* Header */
header {
    background: white;
    padding: 20px 0;
    border-bottom: 1px solid #eee;
    position: sticky;
    top: 0;
    z-index: 50;
}

.header-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo a {
    font-size: 1.5rem;
    font-weight: 800;
    color: var(--primary-color);
    text-decoration: none;
    letter-spacing: -0.5px;
}

.logo span {
    font-weight: 300;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 30px;
}

.nav-links a {
    text-decoration: none;
    color: var(--text-color);
    font-weight: 500;
    font-size: 0.95rem;
    transition: color var(--transition-speed);
}

.nav-links a:hover {
    color: var(--accent-color);
}

.header-actions {
    display: flex;
    gap: 15px;
    align-items: center;
}

.icon-button {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--text-color);
    position: relative;
    padding: 5px;
    border-radius: 50%;
    transition: background-color var(--transition-speed);
}

.icon-button:hover {
    background-color: var(--secondary-color);
}

.cart-count {
    position: absolute;
    top: -2px;
    right: -2px;
    background-color: var(--accent-color);
    color: white;
    font-size: 0.7rem;
    padding: 2px 5px;
    border-radius: 10px;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 12px 28px;
    border-radius: 4px;
    text-decoration: none;
    font-weight: 600;
    cursor: pointer;
    transition: all var(--transition-speed);
    border: 2px solid transparent;
}

.btn-primary {
    background-color: var(--primary-color);
    color: white;
}

.btn-primary:hover {
    background-color: #333;
}

.btn-secondary {
    background-color: transparent;
    border-color: var(--primary-color);
    color: var(--primary-color);
}

.btn-secondary:hover {
    background-color: var(--primary-color);
    color: white;
}

.btn-link {
    padding: 0;
    color: var(--accent-color);
    text-decoration: underline;
}

/* Hero Section */
.hero {
    padding: 80px 0;
    background-color: #fafafa;
}

.hero-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: 60px;
}

.hero-content .eyebrow {
    text-transform: uppercase;
    font-size: 0.85rem;
    font-weight: 700;
    color: var(--accent-color);
    margin-bottom: 15px;
    display: block;
}

.hero-content h1 {
    font-size: 3.5rem;
    line-height: 1.1;
    margin-bottom: 25px;
    font-weight: 800;
}

.hero-content p {
    font-size: 1.1rem;
    color: var(--text-light);
    margin-bottom: 35px;
}

.hero-cta {
    display: flex;
    gap: 15px;
}

.hero-image img {
    width: 100%;
    height: auto;
    border-radius: 8px;
    box-shadow: 0 20px 40px rgba(0,0,0,0.1);
}

/* Featured Products */
.featured-products {
    padding: 100px 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 40px;
}

.section-header h2 {
    font-size: 2rem;
}

.view-all {
    color: var(--text-light);
    text-decoration: none;
    font-weight: 500;
    border-bottom: 1px solid var(--text-light);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 30px;
}

.product-card {
    position: relative;
    transition: transform var(--transition-speed);
}

.product-image {
    position: relative;
    overflow: hidden;
    border-radius: 4px;
    background-color: var(--secondary-color);
    aspect-ratio: 4/5;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-speed);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.add-to-cart {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    background: var(--primary-color);
    color: white;
    border: none;
    padding: 12px;
    font-weight: 600;
    transform: translateY(100%);
    transition: transform var(--transition-speed);
    cursor: pointer;
}

.product-card:hover .add-to-cart {
    transform: translateY(0);
}

.product-info {
    margin-top: 15px;
}

.product-info h3 a {
    text-decoration: none;
    color: var(--text-color);
    font-size: 1rem;
    font-weight: 600;
}

.product-info .price {
    color: var(--text-light);
    margin-top: 5px;
}

/* Deals Section */
.deals {
    padding: 60px 0;
}

.deals-banner {
    background-color: #e3f2fd;
    padding: 80px 40px;
    border-radius: 12px;
    text-align: center;
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: 15px;
}

.deals-content p {
    font-size: 1.2rem;
    margin-bottom: 30px;
}

/* Editorial Section */
.editorial {
    padding: 100px 0;
}

.editorial-grid {
    display: grid;
    grid-template-columns: 1fr 1.2fr;
    gap: 60px;
    align-items: center;
}

.editorial-main h2 {
    font-size: 2.5rem;
    margin-bottom: 25px;
}

.editorial-main p {
    font-size: 1.1rem;
    color: var(--text-light);
    margin-bottom: 30px;
}

.editorial-images img {
    width: 100%;
    border-radius: 8px;
}

/* Footer */
footer {
    background-color: var(--primary-color);
    color: white;
    padding: 80px 0 40px;
}

footer .logo a {
    color: white;
}

.footer-grid {
    display: grid;
    grid-template-columns: 1.5fr 1fr 1fr 1.5fr;
    gap: 40px;
    margin-bottom: 60px;
}

.footer-brand p {
    margin-top: 20px;
    color: #999;
}

.footer-links h3, .footer-newsletter h3 {
    font-size: 1.1rem;
    margin-bottom: 25px;
}

.footer-links ul {
    list-style: none;
}

.footer-links li {
    margin-bottom: 12px;
}

.footer-links a {
    color: #999;
    text-decoration: none;
    transition: color var(--transition-speed);
}

.footer-links a:hover {
    color: white;
}

.footer-newsletter p {
    color: #999;
    margin-bottom: 20px;
}

.newsletter-form {
    display: flex;
    gap: 10px;
}

.newsletter-form input {
    flex-grow: 1;
    padding: 10px 15px;
    border-radius: 4px;
    border: none;
}

.footer-bottom {
    padding-top: 40px;
    border-top: 1px solid #333;
    text-align: center;
    color: #666;
    font-size: 0.9rem;
}

/* Mobile Responsive */
.mobile-nav-toggle {
    display: none;
}

@media (max-width: 992px) {
    .hero-container, .editorial-grid {
        grid-template-columns: 1fr;
    }

    .hero-content h1 {
        font-size: 2.5rem;
    }

    .footer-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 768px) {
    .nav-links {
        display: none; /* In a real app, implement mobile menu */
    }

    .hero {
        padding: 40px 0;
    }

    .hero-content h1 {
        font-size: 2.2rem;
    }
}

/* Focus States */
a:focus-visible, button:focus-visible, input:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}
